-- MySQL:
CREATE DATABASE school;
USE school;

-- PostgreSQL:
-- CREATE DATABASE school;
-- psql command: \connect school

-- SQLite opens or creates a database file:
-- sqlite3 school.db

ALTER TABLE products ADD COLUMN active INTEGER NOT NULL DEFAULT 1;

SELECT name,
       CASE WHEN price_cents >= 1000 THEN 'premium'
            ELSE 'standard' END AS price_group
FROM products;

SELECT name FROM products WHERE active = 1
UNION ALL
SELECT name FROM products WHERE price_cents = 0;

CREATE VIEW active_products AS
SELECT product_id, name, price_cents
FROM products WHERE active = 1;

INSERT INTO products (product_id, name, price_cents)
VALUES (1, 'Sensor', 1300)
ON CONFLICT(product_id) DO UPDATE
SET price_cents = excluded.price_cents;
